import{_ as e,H as t,f as A,i}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"阶段自测题（二）","description":"","frontmatter":{},"headers":[{"level":2,"title":"专有模型微调","slug":"专有模型微调","link":"#专有模型微调","children":[]},{"level":2,"title":"设计一个评估模型","slug":"设计一个评估模型","link":"#设计一个评估模型","children":[]},{"level":2,"title":"真实项目","slug":"真实项目","link":"#真实项目","children":[]}],"relativePath":"AI大模型项目落地实战/阶段自测题（二）.md","filePath":"AI大模型项目落地实战/阶段自测题（二）.md","lastUpdated":1795453306000}'),a={name:"AI大模型项目落地实战/阶段自测题（二）.md"};function B(s,E,n,r,o,l){return t(),A("div",null,[...E[0]||(E[0]=[i('<h1 id="阶段自测题-二" tabindex="-1">阶段自测题（二） <a class="header-anchor" href="#阶段自测题-二" aria-label="Permalink to &quot;阶段自测题（二）&quot;">​</a></h1><p>你好，我是晓蕾。咱们的课程即将结束，在发布结束语之前，小编为你带来了阶段自测题（二）。</p><p>题目针对课程的第四、五、六章，分别涵盖了专有模型微调、评估模型设计、真实项目分析三个部分的知识点，欢迎来挑战！</p><h2 id="专有模型微调" tabindex="-1">专有模型微调 <a class="header-anchor" href="#专有模型微调" aria-label="Permalink to &quot;专有模型微调&quot;">​</a></h2><p>题目一：你认为什么时候需要微调大模型？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/%25E9%2598%25B6%25E6%25AE%25B5%25E8%2587%25AA%25E6%25B5%258B%25E9%25A2%2598%25EF%25BC%2588%25E4%25BA%258C%25EF%25BC%2589/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/%25E9%2598%25B6%25E6%25AE%25B5%25E8%2587%25AA%25E6%25B5%258B%25E9%25A2%2598%25EF%25BC%2588%25E4%25BA%258C%25EF%25BC%2589/1.png" alt=""></a></p><p>题目二：微调数据。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/%25E9%2598%25B6%25E6%25AE%25B5%25E8%2587%25AA%25E6%25B5%258B%25E9%25A2%2598%25EF%25BC%2588%25E4%25BA%258C%25EF%25BC%2589/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/%25E9%2598%25B6%25E6%25AE%25B5%25E8%2587%25AA%25E6%25B5%258B%25E9%25A2%2598%25EF%25BC%2588%25E4%25BA%258C%25EF%25BC%2589/2.png" alt=""></a></p><p>微调大模型的数据不够，怎么办？请简述生成更多训练数据的过程。</p><p>题目三：模型测评。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/%25E9%2598%25B6%25E6%25AE%25B5%25E8%2587%25AA%25E6%25B5%258B%25E9%25A2%2598%25EF%25BC%2588%25E4%25BA%258C%25EF%25BC%2589/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/%25E9%2598%25B6%25E6%25AE%25B5%25E8%2587%25AA%25E6%25B5%258B%25E9%25A2%2598%25EF%25BC%2588%25E4%25BA%258C%25EF%25BC%2589/3.png" alt=""></a></p><ol><li><p>完成模型训练后，我们通常会进行模型能力测评。模型能力测评分为三种，人工测评、通用测评和私有 task 测评。它们分别是什么意思？</p></li><li><p>人工测评、通用测评、私有 task 测评，分别会在什么时候用到？</p></li></ol><h2 id="设计一个评估模型" tabindex="-1">设计一个评估模型 <a class="header-anchor" href="#设计一个评估模型" aria-label="Permalink to &quot;设计一个评估模型&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/%25E9%2598%25B6%25E6%25AE%25B5%25E8%2587%25AA%25E6%25B5%258B%25E9%25A2%2598%25EF%25BC%2588%25E4%25BA%258C%25EF%25BC%2589/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/%25E9%2598%25B6%25E6%25AE%25B5%25E8%2587%25AA%25E6%25B5%258B%25E9%25A2%2598%25EF%25BC%2588%25E4%25BA%258C%25EF%25BC%2589/4.png" alt=""></a></p><p>题目四：什么是评估专家模型？它的作用是什么？</p><p>题目四：评估模型数据集在评估专家模型的数据集准备中，我们讲过三类数据集，分别是 KTO、DPO、RLHF，它们是什么意思？适用于什么场景呢？</p><p>题目五：请简述评估方法的核心原理。</p><h2 id="真实项目" tabindex="-1">真实项目 <a class="header-anchor" href="#真实项目" aria-label="Permalink to &quot;真实项目&quot;">​</a></h2><p>题目六：我们讲过快速验证能否利用大模型处理其他行业（建筑行业）的基础数据，还记得这个快速验证的过程是怎么样的吗？请你简述。如果后续遇到新项目，相信你一定能举一反三，快速验证！</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/%25E9%2598%25B6%25E6%25AE%25B5%25E8%2587%25AA%25E6%25B5%258B%25E9%25A2%2598%25EF%25BC%2588%25E4%25BA%258C%25EF%25BC%2589/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/%25E9%2598%25B6%25E6%25AE%25B5%25E8%2587%25AA%25E6%25B5%258B%25E9%25A2%2598%25EF%25BC%2588%25E4%25BA%258C%25EF%25BC%2589/5.png" alt=""></a></p><p>以上题目，欢迎挑战！如果有疑问，也可以进入课程交流群和大家一起讨论。</p><p>我们结束语见！</p>',22)])])}const g=e(a,[["render",B]]);export{h as __pageData,g as default};
